    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Previous literature about HBV amongst refugees has mostly reported outcomes amongst those in high-­ income countries. A systematic review of HBV by Rossi et al. identified an overall prevalence of 7.2% amongst refugees and migrants arriving in low-­ endemic regions... Another systematic review of refugee children arriving in high-­ income countries reported hepatitis B prevalence of 3%.",
      "reason": "The text describes the current state of knowledge by citing previous systematic reviews regarding HBV prevalence in refugees in high-income countries, contrasting this with the lack of information for LMIC."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "This systematic review is the first to describe the prevalence of hepatitis B amongst refugees, asylum seekers and IDPs in LMIC. This topic is of public health relevance as LMIC have the highest burden of hepatitis B, and host the most refugees... The limited high-­ quality evidence about prevalence and risk factors for hepatitis B amongst refugees in LMIC highlights the need for further characterization to inform appropriate public health responses",
      "reason": "The authors explain the importance of the review by highlighting the high burden of HBV in LMIC, the lack of previous studies in this specific population (refugees in LMIC), and the need for evidence to inform public health responses."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "No previous studies have assessed the prevalence of HBV amongst refugees in LMIC, where most of the global population of refugees reside.",
      "reason": "The authors explicitly state that no previous studies have assessed the prevalence of HBV amongst refugees in LMIC, thereby justifying the need for this specific review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a prevalence review, not a review of intervention effects."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a prevalence review, not a review of complex interventions or delivery contexts."
    }
  ],
  "confidence": 100
