{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Inclusion criteria were articles in English language with full-­ text availability reporting the prevalence of HBV amongst refugees, asylum seekers and/or IDPs currently living in LMIC. LMIC were defined according to World Bank classification. 27 We included studies that measured HBV prevalence using hepatitis B surface antigen (HBsAg) and/or hepatitis B virus DNA. Given few existing studies on this topic, inclusion criteria were broad and no limits were applied for age, setting (e.g. camp, clinic, hospital, community), sampling method or number of participants.",
      "reason": "The authors specify the study characteristics used for eligibility, including population (refugees, asylum seekers, IDPs), setting (LMIC), and outcome measures (HBsAg, HBV DNA)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Inclusion criteria were articles in English language with full-­ text availability... Exclusion criteria were case studies, case series, conference abstracts, modelling studies, economic evaluations or studies from high-­ income countries",
      "reason": "The authors specify report characteristics including language (English), publication status (full-text availability), and document type (excluding conference abstracts)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not distinguish between exclusion because outcomes were not measured and exclusion because outcome results were not reported. The PRISMA flow diagram (Figure 1) only lists 'HBV not outcome' as a reason for exclusion."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "table_3",
      "quote": "N/A",
      "reason": "The authors indicate in the PRISMA checklist that synthesis methods are not applicable, implying no formal synthesis (meta-analysis) was performed, thus no grouping for synthesis was required."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "While the authors state that inclusion criteria were broad due to few existing studies, they do not provide specific rationales for the notable restrictions applied, such as the exclusion of non-English language articles or studies from high-income countries."
    }
  ],
  "confidence": 95
}

